package com.beatoflove.standardcalculator;
import android.app.*;import android.widget.*;import java.math.*;import java.util.*;import static com.beatoflove.standardcalculator.FinancialMath.*;
final class FinancialPanel extends PanelUi {
 final CalculatorEngine engine=new CalculatorEngine(); BigDecimal rate=new BigDecimal("7"),gt=BigDecimal.ZERO; int scale=2; RoundingMode rounding=RoundingMode.HALF_UP; final ArrayList<String> tape=new ArrayList<>();
 final android.content.SharedPreferences store;
 FinancialPanel(Activity a){super(a);store=a.getSharedPreferences("financial531",0);try{rate=new BigDecimal(store.getString("rate","7"));gt=new BigDecimal(store.getString("gt","0"));scale=store.getInt("scale",2);rounding=RoundingMode.valueOf(store.getString("rounding","HALF_UP"));org.json.JSONArray arr=new org.json.JSONArray(store.getString("tape","[]"));for(int i=0;i<arr.length();i++)tape.add(arr.getString(i));}catch(Exception ignored){}}
 void persist(){while(tape.size()>200)tape.remove(0);store.edit().putString("rate",rate.toPlainString()).putString("gt",gt.toPlainString()).putInt("scale",scale).putString("rounding",rounding.name()).putString("tape",new org.json.JSONArray(tape).toString()).apply();} void attach(LinearLayout page){page.removeAllViews();LinearLayout l=col();l.setPadding(dp(8),dp(3),dp(8),dp(4));page.addView(l,new LinearLayout.LayoutParams(-1,-1));Spinner mode=spin(l,"Financial · Mode",new String[]{"Accounting","Business","Finance","Investment"});LinearLayout body=col();l.addView(body,new LinearLayout.LayoutParams(-1,0,1));selected(mode,()->{body.removeAllViews();int i=mode.getSelectedItemPosition();if(i<=0)account(body);else tools(body,i);});}
 void account(LinearLayout l){TextView status=text("",12,MUTE,false);l.addView(status,new LinearLayout.LayoutParams(-1,0,.8f));fitText(status,12);TextView out=result(l);out.setLayoutParams(new LinearLayout.LayoutParams(-1,0,1.5f));fitText(out,24);out.setOnClickListener(v->new AlertDialog.Builder(a).setTitle("Full result").setMessage(out.getText()).setPositiveButton("Close",null).show());Runnable render=()->{status.setText("TAX "+rate+"% · FIX "+scale+" · "+rounding+" · GT "+gt.toPlainString());try{out.setText(money(dec(engine.getDisplay()),scale,rounding));}catch(Exception e){out.setText(engine.getDisplay());}};render.run();keys(l,new String[][]{{"TAX+","TAX−","RATE","GT"},{"COST","SELL","MARGIN","MU"},{"MC","MR","M+","M−"},{"%","CE","C","⌫"},{"7","8","9","÷"},{"4","5","6","×"},{"1","2","3","−"},{"00","0",".","+"},{"000","±","ROUND","="}},k->{try{switch(k){case "RATE":EditText e=new EditText(a);e.setText(rate.toPlainString());new AlertDialog.Builder(a).setTitle("Tax rate %").setView(e).setPositiveButton("Save",(d,w)->{try{BigDecimal x=dec(e.getText().toString());need(x.signum()>=0,"Invalid rate");rate=x;persist();render.run();}catch(Exception ex){out.setText("Invalid rate");}}).setNegativeButton("Cancel",null).show();return;case "ROUND":new AlertDialog.Builder(a).setTitle("Rounding").setItems(new String[]{"FIX 0","FIX 2","FIX 3","FIX 4","Half up","Up (away from zero)","Down (towards zero)"},(d,i)->{if(i<4)scale=new int[]{0,2,3,4}[i];else rounding=new RoundingMode[]{RoundingMode.HALF_UP,RoundingMode.UP,RoundingMode.DOWN}[i-4];persist();render.run();}).show();return;case "GT":out.setText(money(gt,scale,rounding));return;case "COST":case "SELL":case "MARGIN":case "MU":profitDialog(k);return;case "TAX+":case "TAX−":BigDecimal pre=dec(engine.getDisplay());BigDecimal ans=tax(pre,rate,k.equals("TAX−"));gt=gt.add(ans);tape.add(pre+" "+k+" = "+ans);persist();engine.useHistoryResult("Tax result\n"+ans.toPlainString());out.setText(money(ans,scale,rounding));status.setText("TAX "+rate+"% · GT "+gt);return;case "00":case "000":for(int i=0;i<k.length();i++)engine.press("0");break;default:engine.press(k);if(k.equals("=")&&!engine.hasError()){BigDecimal v=dec(engine.getDisplay());gt=gt.add(v);tape.add(engine.getExpression()+" = "+v);persist();}}render.run();}catch(Exception ex){out.setText("Error: "+ex.getMessage());}});action(l,"Tape / Grand Total",()->new AlertDialog.Builder(a).setTitle("Accounting tape").setMessage(String.join("\n",tape)+"\nGT = "+money(gt,scale,rounding)).setPositiveButton("Close",null).setNeutralButton("Clear",(d,w)->{tape.clear();gt=BigDecimal.ZERO;persist();render.run();}).show());TextView tapeButton=(TextView)l.getChildAt(l.getChildCount()-1);tapeButton.setLayoutParams(new LinearLayout.LayoutParams(-1,0,1f));fitText(tapeButton,15);}
 void profitDialog(String k){LinearLayout l=col();EditText x=input(l,k.equals("COST")?"Selling price": "Cost","",false), y=input(l,k.equals("COST")||k.equals("SELL")?"Margin %":"Selling price","",false);TextView o=result(l);action(l,"Calculate",()->{try{BigDecimal c=dec(x.getText().toString()),s=dec(y.getText().toString());BigDecimal v=k.equals("COST")?c.multiply(ONE.subtract(pct(s)),MC):k.equals("SELL")?div(c,ONE.subtract(pct(s))):div(s.subtract(c),k.equals("MU")?c:s).multiply(H);o.setText(money(v,scale,rounding));}catch(Exception e){o.setText("Error");}});new AlertDialog.Builder(a).setTitle(k).setView(l).setPositiveButton("Close",null).show();}
 static final String[][] NAMES={{},{"VAT","Withholding Tax","Profit & Margin","Markup / Markdown","Discount","Break-even","Unit Cost"},{"Loan & Installment","Simple Interest","Compound Interest","Time Value of Money","Depreciation","Amortization"},{"ROI","NPV","IRR","Payback Period","CAGR","Future Value"}};
 void tools(LinearLayout l,int m){Spinner s=spin(l,"Tool",NAMES[m]);TextView open=key("Open calculator",BLUE,BG,()->{int p=s.getSelectedItemPosition();if(p<0)return;String title=NAMES[m][p];ScrollView sc=new ScrollView(a);sc.setFillViewport(true);LinearLayout b=col();b.setPadding(dp(8),dp(4),dp(8),dp(4));sc.addView(b);form(b,title);new AlertDialog.Builder(a).setTitle(title).setView(sc).setPositiveButton("Close",null).show();});l.addView(open,new LinearLayout.LayoutParams(-1,dp(48)));l.addView(text("Select a tool to calculate. Long forms and reports open in a separate dialog.",12,MUTE,false));}
 void form(LinearLayout l,String n){String[] fields;switch(n){case "VAT":fields=new String[]{"Net amount","VAT %"};break;case "Withholding Tax":fields=new String[]{"Taxable base","Withholding %"};break;case "Profit & Margin":case "ROI":fields=new String[]{"Cost / Investment","Revenue / Total proceeds"};break;case "Markup / Markdown":fields=new String[]{"Base price","Markup %","Markdown %"};break;case "Discount":fields=new String[]{"Price","First discount %","Second discount %"};break;case "Break-even":fields=new String[]{"Fixed cost","Selling price / unit","Variable cost / unit"};break;case "Unit Cost":fields=new String[]{"Total cost","Quantity"};break;case "Loan & Installment":case "Amortization":fields=new String[]{"Principal","Annual nominal interest %","Months"};break;case "Simple Interest":case "Compound Interest":case "Future Value":fields=new String[]{"Principal","Annual interest %","Years"};break;case "Time Value of Money":fields=new String[]{"Present value","Future value","Payment per period","Periods","Rate per period %"};break;case "Depreciation":fields=new String[]{"Cost","Residual value","Useful life (years)"};break;case "NPV":fields=new String[]{"Discount rate % per period","Cash flows (initial; year 1; …)"};break;case "IRR":case "Payback Period":fields=new String[]{"Cash flows (initial; year 1; …)"};break;default:fields=new String[]{"Beginning value","Ending value","Years"};} Spinner tvm=n.equals("Time Value of Money")?spin(l,"Solve for",new String[]{"FV","PV","PMT","N","I/Y"}):null;EditText[] e=new EditText[fields.length];for(int j=0;j<e.length;j++)e[j]=input(l,fields[j],n.equals("VAT")&&j==1?"7":"",fields[j].startsWith("Cash flows"));TextView o=result(l);action(l,"Calculate",()->{try{String[] v=new String[e.length];for(int i=0;i<v.length;i++)v[i]=e[i].getText().toString();o.setText(FinancialMath.calc(n,v,tvm==null?0:tvm.getSelectedItemPosition()));}catch(Exception ex){o.setText("Error: "+ex.getMessage());}});l.addView(text("คำนวณจากข้อมูลที่กรอก · ตรวจสอบเงื่อนไขภาษีและสัญญาจริง",12,MUTE,false));}
}
